398 | namespace time_internal {
399 | 
400 | // Provides value storage and comparison/math operations common to all time

401 | // classes. Each subclass provides for strong type-checking to ensure
402 | // semantically meaningful comparison/math of time values from the same clock
403 | // source or timeline.
404 | template <class TimeClass>
405 | class TimeBase {
406 |  public:
407 |   static constexpr int64_t kHoursPerDay = 24;
408 |   static constexpr int64_t kSecondsPerMinute = 60;
409 |   static constexpr int64_t kMinutesPerHour = 60;
410 |   static constexpr int64_t kSecondsPerHour =
411 |       kSecondsPerMinute * kMinutesPerHour;
412 |   static constexpr int64_t kMillisecondsPerSecond = 1000;
413 |   static constexpr int64_t kMillisecondsPerDay =
414 |       kMillisecondsPerSecond * kSecondsPerHour * kHoursPerDay;
415 |   static constexpr int64_t kMicrosecondsPerMillisecond = 1000;
416 |   static constexpr int64_t kMicrosecondsPerSecond =
417 |       kMicrosecondsPerMillisecond * kMillisecondsPerSecond;
418 |   static constexpr int64_t kMicrosecondsPerMinute =
419 |       kMicrosecondsPerSecond * kSecondsPerMinute;
420 |   static constexpr int64_t kMicrosecondsPerHour =
421 |       kMicrosecondsPerMinute * kMinutesPerHour;
422 |   static constexpr int64_t kMicrosecondsPerDay =
423 |       kMicrosecondsPerHour * kHoursPerDay;
424 |   static constexpr int64_t kMicrosecondsPerWeek = kMicrosecondsPerDay * 7;
425 |   static constexpr int64_t kNanosecondsPerMicrosecond = 1000;
426 |   static constexpr int64_t kNanosecondsPerMillisecond =
427 |       kNanosecondsPerMicrosecond * kMicrosecondsPerMillisecond;
428 |   static constexpr int64_t kNanosecondsPerSecond =
429 |       kNanosecondsPerMicrosecond * kMicrosecondsPerSecond;
430 | 
431 |   // Warning: Be careful when writing code that performs math on time values,
432 |   // since it's possible to produce a valid "zero" result that should not be
433 |   // interpreted as a "null" value. If you find yourself using this method or
434 |   // the zero-arg default constructor, please consider using an optional to
435 |   // express the null state.
436 |   //
437 |   // Returns true if this object has not been initialized (probably).
438 |   constexpr bool is_null() const { return us_ == 0; }
439 | 
440 |   // Returns true if this object represents the maximum/minimum time.
441 |   constexpr bool is_max() const { return *this == Max(); }
442 |   constexpr bool is_min() const { return *this == Min(); }
443 |   constexpr bool is_inf() const { return is_min() || is_max(); }
444 | 
445 |   // Returns the maximum/minimum times, which should be non-null and
446 |   // greater/less than than any reasonable time with which we might compare it.
447 |   static constexpr TimeClass Max() {
448 |     return TimeClass(std::numeric_limits<int64_t>::max());
449 |   }
450 | 
451 |   static constexpr TimeClass Min() {
452 |     return TimeClass(std::numeric_limits<int64_t>::min());
453 |   }
454 | 
455 |   // For legacy serialization only. When serializing to `base::Value`, prefer
456 |   // the helpers from //base/json/values_util.h instead. Otherwise, use
457 |   // `Time::ToDeltaSinceWindowsEpoch()` for `Time` and
458 |   // `TimeDelta::InMicroseconds()` for `TimeDelta`. See http://crbug.com/634507.
459 |   constexpr int64_t ToInternalValue() const { return us_; }
460 | 
461 |   // The amount of time since the origin (or "zero") point. This is a syntactic
462 |   // convenience to aid in code readability, mainly for debugging/testing use
463 |   // cases.
464 |   //
465 |   // Warning: While the Time subclass has a fixed origin point, the origin for
466 |   // the other subclasses can vary each time the application is restarted.
467 |   constexpr TimeDelta since_origin() const;
468 | 
469 |   // Returns |this| snapped to the next tick, given a |tick_phase| and
470 |   // repeating |tick_interval| in both directions. |this| may be before,
471 |   // after, or equal to the |tick_phase|.
472 |   constexpr TimeClass SnappedToNextTick(TimeClass tick_phase,
473 |                                         TimeDelta tick_interval) const {
474 |     // |interval_offset| is the offset from |this| to the next multiple of
475 |     // |tick_interval| after |tick_phase|, possibly negative if in the past.
476 |     TimeDelta interval_offset = (tick_phase - *this) % tick_interval;
477 |     // If |this| is exactly on the interval (i.e. offset==0), don't adjust.
478 |     // Otherwise, if |tick_phase| was in the past, adjust forward to the next
479 |     // tick after |this|.
480 |     if (!interval_offset.is_zero() && tick_phase < *this) {
481 |       interval_offset += tick_interval;
