492 |   // Return a new time modified by some delta.
493 |   constexpr TimeClass operator+(TimeDelta delta) const;
494 |   constexpr TimeClass operator-(TimeDelta delta) const;
495 | 
496 |   // Modify by some time delta.
497 |   constexpr TimeClass& operator+=(TimeDelta delta) {
