547 |   // following: ((1970-1601)*365+89)*24*60*60*1000*1000, where 89 is the number
548 |   // of leap year days between 1601 and 1970: (1970-1601)/4 excluding 1700,
549 |   // 1800, and 1900.
550 |   static constexpr int64_t kMicrosecondsFromWindowsToUnixEpoch =
551 |       INT64_C(11644473600000000);
